#pragma once

#include <span>
#include <string_view>

namespace prism::gui_app {

// What the About window shows, generated by CMake from what this build links
// (cmake/ThirdPartyNotices.cmake, gui_app/about_info.cpp.in).

struct ThirdPartyComponent {
    std::string_view name;     // with its version, e.g. "SDL 3.4.18"
    std::string_view licence;  // e.g. "zlib"
};

// The "Required Notice:" line of Prism's LICENSE.md.
[[nodiscard]] std::string_view required_notice();

[[nodiscard]] std::span<const ThirdPartyComponent> third_party_components();

// The full text of THIRD_PARTY_NOTICES.txt.
[[nodiscard]] std::string_view third_party_notices();

}  // namespace prism::gui_app
